export class ConstructBuildError extends Error {
  constructor(category, message) {
    super(message);
    this.name = 'ConstructBuildError';
    this.category = category;
    this.exitCode = 1;
  }
}

function toIntegerBigInt(value, label) {
  if (typeof value === 'bigint') {
    return value;
  }
  if (typeof value === 'number' && Number.isInteger(value)) {
    return BigInt(value);
  }
  throw new ConstructBuildError('format', `${label} requires an integer`);
}

function checkedUnsigned(value, bits, formatCode) {
  const integer = toIntegerBigInt(value, `struct '<${formatCode}'`);
  const maximum = (1n << BigInt(bits)) - 1n;

  if (integer < 0n || integer > maximum) {
    throw new ConstructBuildError(
      'format',
      `struct '<${formatCode}' error during building, given value ${integer}`,
    );
  }
  return integer;
}

export function buildInt8ul(value) {
  const integer = checkedUnsigned(value, 8, 'B');
  return Buffer.from([Number(integer)]);
}

export function buildInt16ul(value) {
  const integer = checkedUnsigned(value, 16, 'H');
  return Buffer.from([
    Number(integer & 0xffn),
    Number((integer >> 8n) & 0xffn),
  ]);
}

export function encodeUtf8(text) {
  return Buffer.from(text, 'utf8');
}

export function buildFixedBytes(expectedLength, content) {
  const expected = toIntegerBigInt(expectedLength, 'Bytes length');
  const bytes = Buffer.from(content);
  const actual = BigInt(bytes.length);

  if (actual !== expected) {
    throw new ConstructBuildError(
      'stream',
      `bytes object of wrong length, expected ${expected}, found ${actual}`,
    );
  }
  return bytes;
}

