function selectQuote(hasSingleQuote, hasDoubleQuote) {
  return hasSingleQuote && !hasDoubleQuote ? '"' : "'";
}

function hexadecimal(byte) {
  return byte.toString(16).padStart(2, '0');
}

export function bytesToPythonRepr(bytes) {
  const quote = selectQuote(bytes.includes(0x27), bytes.includes(0x22));
  const quoteCode = quote.charCodeAt(0);
  let result = `b${quote}`;

  for (const byte of bytes) {
    if (byte === 0x09) {
      result += '\\t';
    } else if (byte === 0x0a) {
      result += '\\n';
    } else if (byte === 0x0d) {
      result += '\\r';
    } else if (byte === 0x5c) {
      result += '\\\\';
    } else if (byte === quoteCode) {
      result += `\\${quote}`;
    } else if (byte >= 0x20 && byte <= 0x7e) {
      result += String.fromCharCode(byte);
    } else {
      result += `\\x${hexadecimal(byte)}`;
    }
  }

  return `${result}${quote}`;
}

export function stringToPythonRepr(text) {
  const quote = selectQuote(text.includes("'"), text.includes('"'));
  let result = quote;

  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (character === quote || character === '\\') {
      result += `\\${character}`;
    } else if (character === '\t') {
      result += '\\t';
    } else if (character === '\n') {
      result += '\\n';
    } else if (character === '\r') {
      result += '\\r';
    } else if (codePoint < 0x20 || codePoint === 0x7f) {
      result += `\\x${hexadecimal(codePoint)}`;
    } else {
      result += character;
    }
  }

  return `${result}${quote}`;
}

