import { parsePythonInteger } from './python-int.mjs';
import { stringToPythonRepr } from './python-repr.mjs';

const OPTIONS = [
  { flag: '--a', key: 'a', metavar: 'A', type: 'int' },
  { flag: '--b', key: 'b', metavar: 'B', type: 'int' },
  { flag: '--c', key: 'c', metavar: 'C', type: 'str' },
  { flag: '--d', key: 'd', metavar: 'D', type: 'int' },
  { flag: '--e', key: 'e', metavar: 'E', type: 'str' },
  { flag: '--f', key: 'f', metavar: 'F', type: 'int' },
  { flag: '--g', key: 'g', metavar: 'G', type: 'int' },
];

function programName(argv) {
  const script = argv[1] ?? 'test17.mjs';
  return script.split(/[\\/]/).pop() || script;
}

function usageLine(program) {
  return `usage: ${program} [-h] --a A --b B --c C --d D --e E --f F --g G`;
}

function printHelp(program) {
  console.log(`${usageLine(program)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
  --f F
  --g G`);
}

function fail(program, message) {
  console.error(usageLine(program));
  console.error(`${program}: error: ${message}`);
  process.exitCode = 2;
  return null;
}

function resolveOption(name) {
  const exact = OPTIONS.find((option) => option.flag === name);
  if (exact !== undefined) {
    return { option: exact };
  }

  const matches = OPTIONS.filter((option) => option.flag.startsWith(name));
  if (matches.length === 1) {
    return { option: matches[0] };
  }
  if (matches.length > 1) {
    return { ambiguous: matches };
  }
  return {};
}

function looksLikeOption(token) {
  if (!token.startsWith('-') || token === '-') {
    return false;
  }
  return !/^-\p{Decimal_Number}+$|^-\p{Decimal_Number}*\.\p{Decimal_Number}+$/u.test(
    token,
  );
}

function isHelpOption(token) {
  return token === '-h' || (token.startsWith('--') && '--help'.startsWith(token));
}

export function parseCommandLine(argv = process.argv) {
  const program = programName(argv);
  const values = {};
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (isHelpOption(token)) {
      printHelp(program);
      process.exitCode = 0;
      return null;
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (!token.startsWith('-') || token === '-') {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const resolved = resolveOption(optionName);

    if (resolved.ambiguous !== undefined) {
      const choices = resolved.ambiguous.map((option) => option.flag).join(', ');
      return fail(program, `ambiguous option: ${optionName} could match ${choices}`);
    }

    if (resolved.option === undefined) {
      extras.push(token);
      continue;
    }

    const option = resolved.option;
    let rawValue;
    if (equalsIndex !== -1) {
      rawValue = token.slice(equalsIndex + 1);
    } else {
      const next = argv[index + 1];
      if (next === undefined || looksLikeOption(next)) {
        return fail(program, `argument ${option.flag}: expected one argument`);
      }
      rawValue = next;
      index += 1;
    }

    if (option.type === 'int') {
      try {
        values[option.key] = parsePythonInteger(rawValue);
      } catch {
        return fail(
          program,
          `argument ${option.flag}: invalid int value: ${stringToPythonRepr(rawValue)}`,
        );
      }
    } else {
      values[option.key] = rawValue;
    }
  }

  const missing = OPTIONS.filter((option) => values[option.key] === undefined);
  if (missing.length > 0) {
    return fail(
      program,
      `the following arguments are required: ${missing
        .map((option) => option.flag)
        .join(', ')}`,
    );
  }

  if (extras.length > 0) {
    return fail(program, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

