node --input-type=module <<'NODE'
import { spawnSync } from 'node:child_process';

const alphabet = [
  ...'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
  ' ', '\t', '\n', '\r', "'", '"', '\\', 'é', '汉', '字', '🙂', '١', '٥',
];
let seed = 0x5eed17;
function random(max) {
  seed = (seed * 1664525 + 1013904223) >>> 0;
  return seed % max;
}
function randomText(maxLength) {
  const length = random(maxLength + 1);
  let text = '';
  for (let index = 0; index < length; index += 1) {
    text += alphabet[random(alphabet.length)];
  }
  return text;
}

for (let test = 0; test < 500; test += 1) {
  const c = randomText(10);
  const e = randomText(10);
  const args = [
    '--a', String(random(256)),
    '--b', String(random(65536)),
    '--c', c,
    '--d', String(Buffer.byteLength(c, 'utf8')),
    '--e', e,
    '--f', String(random(256)),
    '--g', String(Buffer.byteLength(e, 'utf8')),
  ];
  const expected = spawnSync('/workspace/dataset/test17_executable', args, { encoding: 'buffer' });
  const actual = spawnSync('node', ['/output/test17.mjs', ...args], { encoding: 'buffer' });
  if (expected.status !== actual.status || !expected.stdout.equals(actual.stdout) || !expected.stderr.equals(actual.stderr)) {
    console.error(`mismatch at test ${test}`, args);
    console.error('expected status', expected.status, 'actual', actual.status);
    console.error('expected stdout', expected.stdout.toString());
    console.error('actual stdout', actual.stdout.toString());
    console.error('expected stderr', expected.stderr.toString());
    console.error('actual stderr', actual.stderr.toString());
    process.exit(1);
  }
}
console.log('500 randomized black-box cases passed');
